create table if not exists iam.role_definitions (
  id uuid primary key,
  code text not null unique,
  label text not null,
  status text not null default 'active'
    check (status in ('active', 'inactive', 'deprecated')),
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

insert into iam.role_definitions (id, code, label, status)
values
  ('a0000000-0000-4000-8000-000000000001'::uuid, 'staff', 'Nhân viên bán hàng', 'active'),
  ('a0000000-0000-4000-8000-000000000002'::uuid, 'warehouse', 'Thủ kho', 'active'),
  ('a0000000-0000-4000-8000-000000000003'::uuid, 'accountant', 'Kế toán', 'active'),
  ('a0000000-0000-4000-8000-000000000004'::uuid, 'manager', 'Quản lý', 'active')
on conflict (code) do update
set
  label = excluded.label,
  status = 'active',
  updated_at = timezone('utc', now());

create or replace function iam.list_assignable_invitation_roles(
  p_tenant_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = iam, public
as $$
declare
  v_caller uuid := auth.uid();
begin
  if v_caller is null then
    raise exception 'AUTHENTICATION_REQUIRED';
  end if;

  -- Signature is iam.has_permission(uuid, text) — uses auth.uid() internally.
  if not iam.has_permission(p_tenant_id, 'tenant.member.invite') then
    raise exception 'PERMISSION_DENIED';
  end if;

  if not exists (
    select 1
    from iam.memberships m
    where m.tenant_id = p_tenant_id
      and m.user_id = v_caller
      and m.is_active
  ) then
    raise exception 'PERMISSION_DENIED';
  end if;

  return coalesce(
    (
      select jsonb_agg(
        jsonb_build_object(
          'role_id', r.id,
          'label', r.label
        )
        order by r.label
      )
      from iam.role_definitions r
      where r.status = 'active'
        and r.code <> 'owner'
    ),
    '[]'::jsonb
  );
end;
$$;

revoke all on function iam.list_assignable_invitation_roles(uuid) from public;
grant execute on function iam.list_assignable_invitation_roles(uuid) to authenticated;
